compiletime function IR expandGreetBlock(BlockAST source)
	description "Interprets `greet:` blocks and emits a print statement"
	if source.body.length() != 1
		error("GREET001", "a greet: block holds exactly one line, the name to greet", source.span)
		return ir.empty()

	BlockLine line = source.body[0]
	string name = line.tokens[0].text
	return ir.call("print", [ir.stringLiteral("Hello, " + name + "!")])

